#include "motor_driver.hpp"
#include <algorithm>
#include <cmath>
namespace mobile_robot { MotorDriver::MotorDriver(const int pwm_pin,const int direction_pin,const uint8_t pwm_channel,const bool inverted):pwm_pin_(pwm_pin),direction_pin_(direction_pin),pwm_channel_(pwm_channel),inverted_(inverted){} void MotorDriver::begin(const uint32_t frequency_hz,const uint8_t resolution_bits){pinMode(direction_pin_,OUTPUT);ledcSetup(pwm_channel_,frequency_hz,resolution_bits);ledcAttachPin(pwm_pin_,pwm_channel_);pwm_max_=static_cast<uint16_t>((1UL<<resolution_bits)-1UL);stop();} void MotorDriver::set(float normalized_output){if(!std::isfinite(normalized_output)){stop();return;}normalized_output=std::clamp(normalized_output,-1.0F,1.0F);if(inverted_)normalized_output=-normalized_output;const bool forward=normalized_output>=0.0F;digitalWrite(direction_pin_,forward?HIGH:LOW);const float magnitude=std::fabs(normalized_output);ledcWrite(pwm_channel_,static_cast<uint32_t>(magnitude*static_cast<float>(pwm_max_)));} void MotorDriver::stop(){ledcWrite(pwm_channel_,0U);} void MotorDriver::set_inverted(const bool inverted){stop();inverted_=inverted;} bool MotorDriver::inverted() const{return inverted_;} }
